package local.tvmorph.prayercheck;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import android.widget.*;import java.lang.reflect.*;import java.util.concurrent.*;
public class PrayerCityInstrumentation extends Instrumentation{
 Activity activity;WebView web;
 Object field(Object owner,String name)throws Exception{Class<?> c=owner.getClass();while(c!=null){try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(owner);}catch(NoSuchFieldException e){c=c.getSuperclass();}}throw new NoSuchFieldException(name);}
 String js(String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] result={null};runOnMainSync(()->web.evaluateJavascript(code,r->{result[0]=r;latch.countDown();}));if(!latch.await(8,TimeUnit.SECONDS))throw new AssertionError("JS timeout");return result[0];}
 void waitFor(String code)throws Exception{long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){if("true".equals(js(code)))return;Thread.sleep(80);}throw new AssertionError(code);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{activity=startActivitySync(new Intent().setClassName("local.tvmorph.tv","local.tvmorph.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));web=(WebView)field(activity,"web");waitFor("!!(window.ClearTV&&ClearTV.Prayer&&ClearTV.Weather)");js("if(window.MorphBrandLoader)MorphBrandLoader.done();ClearTV.Prayer.openSettings();ClearTV.Weather.search=function(term,callback){window.cityProbe=term;callback(null,[{name:'Montréal',country:'Canada',region:'Québec',latitude:45.5,longitude:-73.5,timezone:'America/Toronto',approximate:false}]);};document.getElementById('prayer-city').focus();TVNative.showKeyboard('prayer-city','');true");Thread.sleep(500);AlertDialog dialog=(AlertDialog)field(activity,"textEntry");if(dialog==null||!dialog.isShowing())throw new AssertionError("Prayer city must open native keyboard on first activation");runOnMainSync(()->{EditText input=dialog.findViewById(android.R.id.edit);if(input==null){android.view.ViewGroup group=(android.view.ViewGroup)dialog.findViewById(android.R.id.custom);input=findInput(group);}if(input==null)throw new AssertionError("EditText missing");input.setText("Montréal");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});waitFor("window.cityProbe==='Montréal'&&document.querySelectorAll('#prayer-city-results button').length===1");js("document.querySelector('#prayer-city-results button').click();true");waitFor("ClearTV.settings.prayer.location.name==='Montréal'");out.putString("result","PASS actual Android prayer city: first activation opens native input; Save submits prayer-search, preserves accented text and selects location with timezone.");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
 EditText findInput(android.view.View v){if(v instanceof EditText)return(EditText)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText e=findInput(g.getChildAt(i));if(e!=null)return e;}}return null;}
}
